typedef float time_value_t;

class string_buf
{
public:
  int pad0;
  int pad4;
  int char_length;
};

class stringx
{
  friend stringx operator+(const stringx& lhs, const stringx& rhs);

protected:
  char* chars;
  string_buf* my_buf;

public:
  stringx();
  stringx(const stringx& cp);
  stringx(const char* str, int len = -1);
  ~stringx();

  void append(const stringx& cp);
  void make_room(int size);
  stringx substr(int i = 0, int n = -1) const;
  const char* c_str() const { return chars; }
};

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;

  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);

  return foo;
}

enum game_mode_t
{
  GAME_MODE_CAREER
};

class os_developer_options
{
  virtual ~os_developer_options();

public:
  enum flags_t
  {
    FLAG_NO_MOVIES = 252,
    FLAG_E3_BUILD = 400
  };

  static os_developer_options* instance;
  static os_developer_options* inst() { return instance; }
  bool is_flagged(flags_t flag) const { return flags[flag]; }

private:
  bool flags[401];
};

class DemoModeManager
{
public:
  bool inDemoMode();
};

struct BeachData
{
  char pad[352];
  int map_location;
  char rest[176];
};

class GlobalDataClass
{
public:
  void unlockLocationMovie(int locationIdx);
};

class Career
{
public:
  class Location
  {
  public:
    bool CheckShowMovie();

  private:
    int my_id;
    bool movie_unlocked;
    bool movie_shown;
    bool board_unlocked;
  };

  char pad[0x1754];
  Location locations[1];
};

class game
{
  char pad0[116];
  game_mode_t game_mode;
  char pad1[432];
  int beachid;

public:
  game_mode_t get_game_mode() { return game_mode; }
  int get_beach_id() { return beachid; }
  int GetSurferIdx(int hero_num) const;
  stringx get_beach_location_name();
  bool play_movie(const char* movie_name, bool canskip, int width = 720, int height = 480);
  void go_next_state();
  void advance_state_play_movie(time_value_t time_inc);
};

extern DemoModeManager dmm;
extern BeachData BeachDataArray[];
extern game* g_game_ptr;
extern GlobalDataClass globalCareerData;
extern Career* g_career;

void debug_print(const char* fmt, ...);
extern "C" int sceGsResetGraph(int mode, int interlace, int omode, int ffmode);
void KSNGL_ReInit();
void nglResetDisplay();

void game::advance_state_play_movie( time_value_t time_inc )
{
  if(get_game_mode() == GAME_MODE_CAREER && !dmm.inDemoMode())
  {
	  if (!os_developer_options::inst()->is_flagged(os_developer_options::FLAG_NO_MOVIES))
	  {
		  if (!(os_developer_options::inst()->is_flagged(os_developer_options::FLAG_E3_BUILD)))
		  {
			  int location, surfer;

			  location = BeachDataArray[g_game_ptr->get_beach_id()].map_location;
			  surfer = g_game_ptr->GetSurferIdx(0);
        globalCareerData.unlockLocationMovie(BeachDataArray[g_game_ptr->get_beach_id()].map_location);
			  if(g_career->locations[location].CheckShowMovie())
			  {
				  debug_print("Playing movie for location #%d\n", location);
          stringx moviename = stringx("BEACHES\\") + g_game_ptr->get_beach_location_name().substr(0, 8);

          sceGsResetGraph( 0, 1, 2, 1 );
          g_game_ptr->play_movie(moviename.c_str(), true, 640, 448);
          KSNGL_ReInit();
          nglResetDisplay();
			  }
		  }
	  }
  }

	go_next_state();
}
